def structural_metrics(rows,prior):
    probs=np.array([r['structure_probabilities'] for r in rows]);gold=np.array([r['structure_gold'] for r in rows]);prior=np.asarray(prior);pp=probs[:,4:].sum(axis=1);truth=gold>=4;heads=np.array([[sum(p[j] for j,(_,h) in enumerate(CLASSES) if h==head) for head in ('VERBAL','NOMINAL','OTHER','ROOT')] for p in probs]);hgold=gold%4
